#!/usr/bin/env bash
set -euo pipefail

if ! command -v node >/dev/null 2>&1; then
  printf '%s\n' 'ERROR: Node.js is required.' >&2
  exit 1
fi
node -e "const [major] = process.versions.node.split('.').map(Number); if (major < 22) { console.error('ERROR: Node.js 22 or later is required.'); process.exit(1); }"

if [ -e claude-card-lab ]; then
  printf '%s\n' 'ERROR: claude-card-lab already exists; choose a fresh parent directory.' >&2
  exit 1
fi

mkdir -p claude-card-lab/src claude-card-lab/test claude-card-lab/reference
cd claude-card-lab

cat > CLAUDE.md <<'EOF'
# Repository operating instructions

Read @AGENTS.md before changing files.

Task boundary:
- For the configuration exercise, edit only src/config.mjs.
- The input domain is a non-null configuration object; within that domain, invalid or missing port values use fallback 8080.
- Do not edit test/contract.mjs or reference/answer.mjs.
- Do not add dependencies, use the network, or change package metadata.

Verification:
- Run `node --version` and require Node 22 or later.
- Run `node test/contract.mjs` after the edit.
- Report stdout, stderr, exit status, and `git diff -- src/config.mjs`.

Stop conditions:
- Stop if a command requests network access or a secret.
- Stop if a file outside src/config.mjs would be changed.
- Stop if the test contract is missing or has been modified.

Recovery:
- Preserve the failing output and diff.
- Revert only the learner change to src/config.mjs, then rerun the contract.
EOF

cat > AGENTS.md <<'EOF'
# Shared repository guidance

You are repairing one predicate in `src/config.mjs`.

Input domain:
- `selectPort` receives a non-null configuration object.
- Within that domain, invalid or missing `port` values use the fallback 8080.

Evidence:
- `test/contract.mjs` is the immutable contract.
- `reference/answer.mjs` is an independent reference and must not be copied.

Allowed mutation:
- Only `src/config.mjs` may change.

Required result:
- Preserve the positive and negative cases.
- Make the boundary case for port 1024 pass.
- Run `node test/contract.mjs` and inspect the diff.

Never:
- Edit tests or the reference.
- Run `rm`, network commands, or commands involving secrets.
EOF

cat > src/config.mjs <<'EOF'
export function selectPort(config) {
  if (Number.isInteger(config.port) && config.port > 1024 && config.port <= 65535) {
    return config.port;
  }
  return 8080;
}
EOF

cat > test/contract.mjs <<'EOF'
import { selectPort } from '../src/config.mjs';

const cases = [
  ['positive valid port', { port: 3000 }, 3000],
  ['negative low port', { port: 80 }, 8080],
  ['changed boundary port', { port: 1024 }, 1024],
  ['negative high port', { port: 70000 }, 8080],
  ['negative non-integer port', { port: 3000.5 }, 8080],
];

let passed = 0;
let failed = 0;
for (const [name, input, expected] of cases) {
  const actual = selectPort(input);
  if (actual === expected) {
    console.log(`PASS ${name}`);
    passed += 1;
  } else {
    console.log(`FAIL ${name}: expected ${expected}, got ${actual}`);
    failed += 1;
  }
}
console.log(`SUMMARY passed=${passed} failed=${failed}`);
if (failed !== 0) process.exitCode = 1;
EOF

cat > reference/answer.mjs <<'EOF'
export function selectPort(config) {
  if (Number.isInteger(config.port) && config.port >= 1024 && config.port <= 65535) {
    return config.port;
  }
  return 8080;
}
EOF

printf '%s\n' '--- package files ---'
printf '%s\n' 'CLAUDE.md AGENTS.md src/config.mjs test/contract.mjs reference/answer.mjs'

git init -q
git config user.name 'Project 42 Exercise'
git config user.email 'project42.exercise@example.invalid'
git add CLAUDE.md AGENTS.md src test reference
GIT_AUTHOR_NAME='Project 42 Exercise' GIT_AUTHOR_EMAIL='project42.exercise@example.invalid' GIT_COMMITTER_NAME='Project 42 Exercise' GIT_COMMITTER_EMAIL='project42.exercise@example.invalid' git commit -qm 'fixture baseline'
printf '%s\n' 'SETUP complete: tracked baseline created'
